def creates_triangle(edges, new_edge, n=8):
    adj = [[False]*n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = True
        adj[v][u] = True
    u, v = new_edge
    # Check if adding (u,v) creates a triangle
    for w in range(n):
        if w != u and w != v:
            if adj[u][w] and adj[v][w]:
                return True
    return False

def is_maximal_triangle_free(edges, n=8):
