from itertools import combinations
from pysat.formula import CNF
from pysat.solvers import Solver

n = 8
all_edges = [(u, v) for u in range(n) for v in range(u+1, n)]
edge_idx = {e: i+1 for i, e in enumerate(all_edges)}

cnf = CNF()

# 1. Triangle-free constraints
for i, j, k in combinations(range(n), 3):
    e1 = edge_idx[(i,j)]
    e2 = edge_idx[(j,k)]
    e3 = edge_idx[(i,k)]
    cnf.append([-e1, -e2, -e3])

# Auxiliary variables for maximality
num_base = len(all_edges)  # 28
aux_vars = {}
aux_counter = num_base + 1

for u, v in all_edges:
    for w in range(n):
        if w != u and w != v:
            aux_vars[(u,v,w)] = aux_counter
            aux_counter += 1

# Define aux[u,v,w] <=> (x_{uw} AND x_{vw})
for u, v in all_edges:
    for w in range(n):
        if w != u and w != v:
            a = aux_vars[(u,v,w)]
            uw = edge_idx[(min(u,w), max(u,w))]
            vw = edge_idx[(min(v,w), max(v,w))]
            cnf.append([-a, uw])
            cnf.append([-a, vw])
            cnf.append([-uw, -vw, a])

# 2. Maximality: for each edge (u,v), x_{uv} OR (OR_w aux[u,v,w])
for u, v in all_edges:
    clause = [edge_idx[(u,v)]]
    for w in range(n):
        if w != u and w != v:
            clause.append(aux_vars[(u,v,w)])
    cnf.append(clause)

# 3. Fixed edges
cnf.append([edge_idx[(0,6)]])
cnf.append([edge_idx[(2,6)]])

print("Solving...")
with Solver(name='glucose3', bootstrap_with=cnf) as solver:
    result = solver.solve()
    print(f"SAT: {result}")
    if result:
        model = solver.get_model()
        solution_edges = []
        for e, idx in edge_idx.items():
            if model[idx-1] > 0:
                solution_edges.append(e)
        print(f"Edges: {solution_edges}")
